      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input: values (List[List[int]])",
      "action": "ctx['values'] = ctx['arg0']",
      "next": 3
    },
    {
      "id": 3,
      "type": "process",
      "label": "Initialize r = []",
      "action": "ctx['r'] = []",
      "next": 4
    },
    {
      "id": 4,
      "type": "decision",
      "label": "For each shop i in values",
      "logic": "ctx['i'] < len(ctx['values'])",
      "true_next": 5,
      "false_next": 7
    },
    {
      "id": 5,
      "type": "process",
      "label": "Extend r with items from shop i",
      "action": "ctx['r'].extend(ctx['values'][ctx['i']])",
      "next": 6
    },
    {
      "id": 6,
      "type": "process",
      "label": "Heapify r: heapq.heapify(r)",
      "action": "heapq.heapify(ctx['r'])",
      "next": 4
    },
    {
      "id": 7,
      "type": "process",
      "label": "Initialize ans = 0",
      "action": "ctx['ans'] = 0",
      "next": 8
    },
    {
      "id": 8,
      "type": "decision",
      "label": "For day i from 1 to length of r",
      "logic": "ctx['i'] <= len(ctx['r'])",
      "true_next": 9,
      "false_next": 11
    },
    {
      "id": 9,
      "type": "process",
      "label": "Pop the smallest value from r: val = heapq.heappop(r)",
      "action": "ctx['val'] = heapq.heappop(ctx['r'])",
      "next": 10
    },
    {
      "id": 10,
      "type": "process",
      "label": "Update ans: ans += i * val",
      "action": "ctx['ans'] += ctx['i'] * ctx['val']",
      "next": 8
    },
    {
      "id": 11,
      "type": "end",
      "label": "Output: ans (maximum spending)",
      "output": "ctx['ans']"
    }
  ]
}
